<?php
declare(strict_types=1);

require dirname(__DIR__) . '/auth_store.php';
header('Content-Type: application/json; charset=UTF-8');
header('Cache-Control: no-store, no-cache, must-revalidate');

const TT_EBS_FILE = TT_DATA_DIR . '/accounts.json';
const TT_EBS_ACCOUNT_MASTER = __DIR__ . '/../accounts/accounting_master_v1.json';
const TT_EBS_REALIZATION_POLICY = __DIR__ . '/../accounts/export_realization_policy_v1.json';

function ebs_respond(array $data,int $status=200): never {http_response_code($status);echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function ebs_can_write(array $user): bool {if(($user['role']??'')==='Super Admin')return true;$p=$user['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function ebs_default(): array {return ['revision'=>0,'journals'=>[],'exportCandidates'=>[],'exportReceipts'=>[],'exportBankShortfalls'=>[]];}
function ebs_read(): array {tt_ensure_data_dir();if(!is_file(TT_EBS_FILE))return ebs_default();$h=fopen(TT_EBS_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(ebs_default(),$v):ebs_default();}
function ebs_entity(string $v): string {$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM'],true))ebs_respond(['ok'=>false,'error'=>'Foreign bank shortfall settlement is available for TTI / BRM Pakistan books.'],422);return $v;}
function ebs_json(string $path): array {$raw=is_file($path)?file_get_contents($path):false;$v=$raw?json_decode($raw,true):null;if(!is_array($v))throw new RuntimeException('Accounting policy unavailable.');return $v;}
function ebs_catalog(): array {$out=[];foreach([TT_EBS_ACCOUNT_MASTER,TT_EBS_REALIZATION_POLICY] as $p){$m=ebs_json($p);foreach((array)($m['chart']??$m['accounts']??[]) as $a)if(is_array($a)&&isset($a['code']))$out[(string)$a['code']]=$a;}return $out;}
function ebs_next(array $items,string $prefix): string {$n=count($items)+1;do{$id=$prefix.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function ebs_line(string $account,float $dr,float $cr,array $catalog,array $extra=[]): array {if(!isset($catalog[$account]))ebs_respond(['ok'=>false,'error'=>'Accounting mapping '.$account.' is unavailable.'],422);return array_merge(['account'=>$account,'accountName'=>(string)($catalog[$account]['name']??$account),'debit'=>round($dr,2),'credit'=>round($cr,2)],$extra);}
function ebs_allocated(array $store,string $candidateId): float {$n=0.0;foreach((array)($store['exportReceipts']??[]) as $r)if(is_array($r))foreach((array)($r['allocations']??[]) as $a)if(is_array($a)&&(string)($a['targetId']??'')===$candidateId)$n+=(float)($a['foreignAmount']??0);return round($n,2);}
function ebs_sources(array $store,string $entity): array {$out=[];foreach((array)($store['exportCandidates']??[]) as $id=>$c){if(!is_array($c)||($c['entity']??'')!==$entity||empty($c['journalId']))continue;$type=(string)($c['candidateType']??'');if(!in_array($type,['CUSTOMER_EXPORT_SALE','TG_PAKISTAN_INTERCOMPANY'],true))continue;$total=round((float)($c['transactionAmount']??0),2);if($total<=0)continue;$allocated=ebs_allocated($store,(string)$id);$remaining=max(0,round($total-$allocated,2));if($remaining<=.0001)continue;$meta=is_array($c['meta']??null)?$c['meta']:[];$linked=[];foreach((array)($store['exportReceipts']??[]) as $rid=>$r){if(!is_array($r)||($r['entity']??'')!==$entity||($r['recordType']??'')==='FOREIGN_BANK_SHORTFALL_ADJUSTMENT')continue;foreach((array)($r['allocations']??[]) as $a)if(is_array($a)&&(string)($a['targetId']??'')===(string)$id){$linked[]=['id'=>(string)($r['id']??$rid),'date'=>(string)($r['date']??''),'bankAdviceRef'=>(string)($r['bankAdviceRef']??''),'bankName'=>(string)($r['bankName']??''),'rate'=>(float)($r['realizationRate']??0),'currency'=>(string)($r['transactionCurrency']??''),'receivedForeign'=>(float)($a['foreignAmount']??0)];break;}}usort($linked,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date']));$out[]=['candidateId'=>(string)$id,'type'=>$type,'reference'=>(string)($c['reference']??$id),'contractRef'=>(string)($meta['contractRef']??''),'customer'=>(string)($meta['customer']??$c['counterparty']??''),'currency'=>(string)($c['transactionCurrency']??''),'invoiceForeign'=>$total,'settledForeign'=>$allocated,'remainingForeign'=>$remaining,'functionalAmount'=>(float)($c['functionalAmount']??0),'linkedReceipts'=>$linked];}usort($out,static fn($a,$b)=>strcmp((string)$b['reference'],(string)$a['reference']));return $out;}
function ebs_payload(array $store,string $entity): array {$history=[];foreach((array)($store['exportBankShortfalls']??[]) as $x)if(is_array($x)&&($x['entity']??'')===$entity)$history[]=$x;usort($history,static fn($a,$b)=>strcmp((string)$b['date'],(string)$a['date']));return ['ok'=>true,'entity'=>$entity,'sources'=>ebs_sources($store,$entity),'history'=>array_slice($history,0,30)];}

try{
    $user=tt_require_login();if(!tt_user_can_open_module($user,'Accounts'))ebs_respond(['ok'=>false,'error'=>'Accounts permission required.'],403);
    if($_SERVER['REQUEST_METHOD']==='GET'){$entity=ebs_entity((string)($_GET['entity']??'TTI'));ebs_respond(ebs_payload(ebs_read(),$entity));}
    if($_SERVER['REQUEST_METHOD']!=='POST')ebs_respond(['ok'=>false,'error'=>'Method not allowed.'],405);if(!ebs_can_write($user))ebs_respond(['ok'=>false,'error'=>'Accounts Create / Edit / Approve permission required.'],403);
    $body=json_decode(file_get_contents('php://input')?:'{}',true);if(!is_array($body)||!tt_verify_csrf((string)($body['csrf']??'')))ebs_respond(['ok'=>false,'error'=>'Your session expired. Refresh and try again.'],419);if((string)($body['action']??'')!=='post_shortfall')ebs_respond(['ok'=>false,'error'=>'Unknown shortfall action.'],422);
    $entity=ebs_entity((string)($body['entity']??''));$candidateId=trim((string)($body['candidateId']??''));$receiptId=trim((string)($body['linkedReceiptId']??''));$amount=round((float)($body['foreignShortfall']??0),2);$evidence=trim((string)($body['evidenceRef']??''));$notes=trim((string)($body['notes']??''));$confirmed=!empty($body['confirmedBankCharge']);if(!$confirmed)ebs_respond(['ok'=>false,'error'=>'Accounts must explicitly confirm that this is a genuine foreign/correspondent bank charge.'],422);if($candidateId===''||$receiptId===''||$amount<=0)ebs_respond(['ok'=>false,'error'=>'Select the invoice/TG receivable, linked bank receipt and shortfall amount.'],422);
    tt_ensure_data_dir();$h=fopen(TT_EBS_FILE,'c+');if($h===false||!flock($h,LOCK_EX))throw new RuntimeException('Accounts storage unavailable.');
    try{
        rewind($h);$raw=stream_get_contents($h);$store=$raw?json_decode($raw,true):null;if(!is_array($store))$store=ebs_default();$store=array_replace_recursive(ebs_default(),$store);$candidate=$store['exportCandidates'][$candidateId]??null;if(!is_array($candidate)||($candidate['entity']??'')!==$entity||empty($candidate['journalId']))ebs_respond(['ok'=>false,'error'=>'The selected receivable is no longer available for settlement.'],404);$type=(string)($candidate['candidateType']??'');if(!in_array($type,['CUSTOMER_EXPORT_SALE','TG_PAKISTAN_INTERCOMPANY'],true))ebs_respond(['ok'=>false,'error'=>'Only export or TG intercompany receivables can use this adjustment.'],422);$total=round((float)($candidate['transactionAmount']??0),2);$remaining=max(0,round($total-ebs_allocated($store,$candidateId),2));if($amount>$remaining+.01)ebs_respond(['ok'=>false,'error'=>'Shortfall exceeds the remaining foreign balance.'],422);
        $receipt=$store['exportReceipts'][$receiptId]??null;if(!is_array($receipt)||($receipt['entity']??'')!==$entity||($receipt['recordType']??'')==='FOREIGN_BANK_SHORTFALL_ADJUSTMENT')ebs_respond(['ok'=>false,'error'=>'Select a genuine linked bank receipt.'],422);$linked=false;foreach((array)($receipt['allocations']??[]) as $a)if(is_array($a)&&(string)($a['targetId']??'')===$candidateId){$linked=true;break;}if(!$linked)ebs_respond(['ok'=>false,'error'=>'The selected bank receipt is not linked to this invoice/TG receivable.'],422);$rate=round((float)($receipt['realizationRate']??0),6);if($rate<=0)ebs_respond(['ok'=>false,'error'=>'The linked bank receipt has no usable realization rate.'],422);$currency=(string)($candidate['transactionCurrency']??$receipt['transactionCurrency']??'');$expensePkr=round($amount*$rate,2);$carrying=round((float)($candidate['functionalAmount']??0)*($amount/max(.000001,$total)),2);$catalog=ebs_catalog();$lines=[ebs_line('6810',$expensePkr,0,$catalog,['masterCode'=>'EXP-BANK-SHORTFALL','foreignAmount'=>$amount,'currency'=>$currency,'rate'=>$rate])];$receivableAccount=$type==='TG_PAKISTAN_INTERCOMPANY'?'1240':'1210';$lines[]=ebs_line($receivableAccount,0,$carrying,$catalog,['candidateId'=>$candidateId]);$balance=round($expensePkr-$carrying,2);if($balance>0)$lines[]=ebs_line('7100',0,$balance,$catalog,['fxDirection'=>'Gain']);elseif($balance<0)$lines[]=ebs_line('7100',abs($balance),0,$catalog,['fxDirection'=>'Loss']);$dr=round(array_sum(array_column($lines,'debit')),2);$cr=round(array_sum(array_column($lines,'credit')),2);if(abs($dr-$cr)>.01)throw new RuntimeException('Shortfall journal did not balance.');$adjId=ebs_next((array)$store['exportBankShortfalls'],'FBS');$journalId=ebs_next((array)$store['journals'],'AUTO');$date=(string)($receipt['date']??gmdate('Y-m-d'));$reference=(string)($receipt['bankAdviceRef']??$receiptId).'-FBS';$meta=['shortfallId'=>$adjId,'masterCode'=>'EXP-BANK-SHORTFALL','candidateId'=>$candidateId,'linkedReceiptId'=>$receiptId,'invoiceRef'=>(string)($candidate['reference']??$candidateId),'contractRef'=>(string)(($candidate['meta']['contractRef']??'')),'foreignAmount'=>$amount,'currency'=>$currency,'rate'=>$rate,'expensePkr'=>$expensePkr,'carryingPkr'=>$carrying,'evidenceRef'=>$evidence,'notes'=>$notes,'confirmedBankCharge'=>true];$store['journals'][$journalId]=['id'=>$journalId,'entity'=>$entity,'date'=>$date,'sourceType'=>'EXPORT_FOREIGN_BANK_SHORTFALL','reference'=>$reference,'narration'=>'Foreign/correspondent bank shortfall — '.$reference,'lines'=>$lines,'totalDebit'=>$dr,'totalCredit'=>$cr,'status'=>'Posted','meta'=>$meta,'createdAt'=>gmdate('c'),'createdBy'=>(string)($user['full_name']??$user['username']??'Accounts'),'userId'=>(int)($user['id']??0),'reversalOf'=>null];$adjust=['id'=>$adjId,'entity'=>$entity,'date'=>$date,'candidateId'=>$candidateId,'linkedReceiptId'=>$receiptId,'reference'=>$reference,'invoiceRef'=>(string)($candidate['reference']??$candidateId),'contractRef'=>(string)(($candidate['meta']['contractRef']??'')),'customer'=>(string)(($candidate['meta']['customer']??$candidate['counterparty']??'')),'transactionCurrency'=>$currency,'foreignShortfall'=>$amount,'realizationRate'=>$rate,'pkrAmount'=>$expensePkr,'journalId'=>$journalId,'evidenceRef'=>$evidence,'notes'=>$notes,'status'=>'Accounts Confirmed — Foreign Banking Charge','approvedBy'=>(string)($user['full_name']??$user['username']??'Accounts'),'createdAt'=>gmdate('c')];$store['exportBankShortfalls'][$adjId]=$adjust;
        $shadowId='ERADJ-'.$adjId;$alloc=['targetType'=>$type==='TG_PAKISTAN_INTERCOMPANY'?'INTERCOMPANY_RECEIVABLE':'EXPORT_RECEIVABLE','targetId'=>$candidateId,'foreignAmount'=>$amount,'realizedPkr'=>$expensePkr,'carryingPkr'=>$carrying,'contractRef'=>$adjust['contractRef'],'invoiceRef'=>$adjust['invoiceRef'],'customer'=>$adjust['customer'],'fiRefs'=>[]];$store['exportReceipts'][$shadowId]=['id'=>$shadowId,'recordType'=>'FOREIGN_BANK_SHORTFALL_ADJUSTMENT','entity'=>$entity,'date'=>$date,'bankAdviceRef'=>$reference,'bankAdviceFileRef'=>$evidence,'remitter'=>$adjust['customer'],'transactionCurrency'=>$currency,'foreignAmount'=>$amount,'realizationRate'=>$rate,'grossPkrEquivalent'=>$expensePkr,'bankAccountId'=>(string)($receipt['bankAccountId']??''),'bankName'=>(string)($receipt['bankName']??''),'pkrBankCredit'=>0,'retentionBankAccountId'=>'','retentionForeignAmount'=>0,'retentionPkrEquivalent'=>0,'fiAllocations'=>[],'allocations'=>[$alloc],'deductions'=>[],'journalId'=>$journalId,'separateChargeJournalId'=>null,'status'=>'Foreign Bank Shortfall Adjustment','createdAt'=>gmdate('c'),'createdBy'=>$adjust['approvedBy']];$store['revision']=(int)($store['revision']??0)+1;rewind($h);ftruncate($h,0);fwrite($h,json_encode($store,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));fflush($h);
    }finally{flock($h,LOCK_UN);fclose($h);}
    ebs_respond(ebs_payload($store,$entity)+['adjustment'=>$adjust,'journal'=>$store['journals'][$journalId],'revision'=>$store['revision']]);
}catch(Throwable $e){ebs_respond(['ok'=>false,'error'=>'The foreign banking shortfall adjustment could not be completed.'],500);}

